diagram("mode: sequence
[Client] as c
[Logger] as l
[Auth] as a
[Handler] as h
c -> l : request
l -> a : next()
a -> h : next() if token ok
h --> c : response
@0 c -> l : request
@1 l -> a : next()
@2 a -> h : next() if token ok
@3 h -> c : response");

